SELECT COUNT(*)
  FROM TBL_USER_MST
 WHERE HOSP_CD  = #{cfmHospCd}
   AND USER_ID <> #{cfmUserId}

SELECT COUNT(*)
  FROM TBL_HOSP_MST
 WHERE HOSP_CD   = #{cfmHospCd}
   AND JOB_SEQ   = #{cfmHospSeq}
   AND HOSP_UUID = #{hospUuid}

mapper.update:
UPDATE TBL_JOIN_REQ
   SET HOSP_NM      = #{hospNm}
     , HOSP_CEO     = #{hospCeo}
     , HOSP_TEL     = #{hospTel}
     , HOSP_FAX     = #{hospFax}
     , BUSI_NUM     = #{busiNum}
     , ZIP_CD       = #{zipCd}
     , HOSP_ADDR    = #{hospAddr}
     , HOSP_EXTRADR = #{hospExtradr}
     , WARDCNT      = NULLIF(TRIM(IFNULL(#{wardcnt},'')),'')
     /* ★2026-08-24 프로세스 변경 — 아래 항목들이 <신청 단계에서 이리로> 옮겨 왔다.
        신청은 요양기관기호·요양기관명·신청자정보만 받고, 나머지는 승인 후 이 화면에서 채운다. */
     , OCS_COMPANY  = #{ocsCompany}
     , OCS_USER_ID  = #{ocsUserId}
     , OCS_USER_PW  = #{ocsUserPw}
     , HIRA_CERT_PW = #{hiraCertPw}
     , PC_USE_GB    = NULLIF(TRIM(IFNULL(#{pcUseGb},'')),'')
     , PC_USE_TIME  = #{pcUseTime}
     , PC_USE_STDT  = NULLIF(TRIM(IFNULL(#{pcUseStdt},'')),'')
     , ASQ_DAY      = NULLIF(TRIM(IFNULL(#{asqDay},'')),'')
     , ASQ_BIGO     = #{asqBigo}
     , EVAL_GOAL    = #{evalGoal}
     , CONACT_GB    = NULLIF(TRIM(IFNULL(#{conactGb},'')),'')
     /* 대표자 도장 — 값이 올라온 때만 바꾼다. 빈 값으로 덮으면 이미 올린 도장이 지워진다. */
     , SEAL_IMG     = CASE WHEN TRIM(IFNULL(#{sealImg},''))  = '' THEN SEAL_IMG  ELSE FROM_BASE64(#{sealImg}) END   /* ★2026-08-24 : 이중 인코딩 교정 */
     , SEAL_MIME    = CASE WHEN TRIM(IFNULL(#{sealImg},''))  = '' THEN SEAL_MIME ELSE #{sealMime} END
     , SEAL_NM      = CASE WHEN TRIM(IFNULL(#{sealImg},''))  = '' THEN SEAL_NM   ELSE #{sealNm}   END
     , SEAL_HASH    = CASE WHEN TRIM(IFNULL(#{sealImg},''))  = '' THEN SEAL_HASH ELSE #{sealHash} END
     , UPD_DTTM     = NOW()
     , UPD_USER     = #{cfmUser}
     , UPD_IP       = #{regIp}
 WHERE REQ_NO   = #{reqNo}
   AND HOSP_CD  = #{hospCd}
   AND REQ_STAT IN ('30','40')

UPDATE TBL_HOSPCONT_MST
   SET OCS_COMPANY = CASE WHEN TRIM(IFNULL(OCS_COMPANY,'')) = '' THEN #{ocsCompany} ELSE OCS_COMPANY END
     , OCS_USER_ID = CASE WHEN TRIM(IFNULL(OCS_USER_ID,'')) = '' THEN #{ocsUserId}  ELSE OCS_USER_ID END
     , OCS_USER_PW = CASE WHEN TRIM(IFNULL(OCS_USER_PW,'')) = '' THEN #{ocsUserPw}  ELSE OCS_USER_PW END
     , UPD_DTTM    = NOW()
     , UPD_USER    = #{cfmUser}
     , UPD_IP      = #{regIp}
 WHERE HOSP_CD   = #{hospCd}
   AND ACTION_YN = 'Y'

UPDATE TBL_HOSP_MST
   SET HOSP_NM      = #{hospNm}
     , HOSP_CEO     = #{hospCeo}
     , HOSP_TEL     = #{hospTel}
     , HOSP_FAX     = #{hospFax}
     , BUSI_NUM     = #{busiNum}
     , ZIP_CD       = #{zipCd}
     , HOSP_ADDR    = #{hospAddr}
     , HOSP_EXTRADR = #{hospExtradr}
     , WARDCNT      = NULLIF(TRIM(IFNULL(#{wardcnt},'')),'')
     , UPD_DTTM     = NOW()
     , UPD_USER     = #{cfmUser}
     , UPD_IP       = #{regIp}
 WHERE HOSP_CD   = #{hospCd}
   AND ACTION_YN = 'Y'
